arguments.command:
mkdir -p /root/chk && cat > /root/chk/m2.stan <<'EOF'
data {
  int<lower=0> N;
  array[N] int<lower=0> n;
  array[N] int<lower=0> y;
}
parameters {
  real x;  // log(alpha/beta)
  real z;  // log(alpha+beta)
  vector<lower=0, upper=1>[N] theta;
}
transformed parameters {
  real<lower=0> alpha = exp(x + z) / (1 + exp(x));
  real<lower=0> beta = exp(z) / (1 + exp(x));
}
model {
  target += log(alpha) + log(beta) - 2.5 * log(alpha + beta);
  theta ~ beta(alpha, beta);
  y ~ binomial(n, theta);
}
EOF
cat > /root/chk/chk.R <<'EOF'
library(rstan)
d <- read.csv("/app/data.csv")
f <- sampling(stan_model("/root/chk/m2.stan"), data=list(N=nrow(d), y=as.integer(d$y), n=as.integer(d$n)), chains=4, iter=100000, seed=1, cores=4, refresh=0)
p <- rstan::extract(f, pars=c("alpha","beta"))
cat(mean(p$alpha), mean(p$beta), "\n")
print(summary(f, pars=c("alpha","beta"))$summary)
EOF
Rscript /root/chk/chk.R 2>&1 | tail -6

